    h1 { font-size: 1.5rem; font-weight: 600; margin: 0 0 0.75rem; }
    p { margin: 0; line-height: 1.5; color: #9aa3b2; }
    .error { color: #f87171; }
    .success { color: #4ade80; }
    code {
      user-select: all; word-break: break-all; background: #111827;
      padding: 0.5rem 0.75rem; border-radius: 0.375rem; color: #e8ecf2;
    }
  </style>
</head>
<body>
  <div class="card">
    <h1 id="title">Authorizing&hellip;</h1>
    <p id="message">You can close this tab once the app updates.</p>
  </div>
  <script>
    (function () {
      var params = new URLSearchParams(window.location.search);
      var code = params.get('code');
      var error = params.get('error');
      var errorDescription = params.get('error_description') || error;
      var payload = {
        type: 'aiin_oauth_code',
        code: code,
        state: params.get('state'),
        error: error,
        ts: Date.now()
      };

      // The opener may be served from localhost (dev) or fa1.dev (prod);
      // the payload carries no secrets — only the short-lived code.
      var delivered = false;
      if (window.opener) {
        try { window.opener.postMessage(payload, '*'); delivered = true; }
        catch (e) { /* cross-origin or closed opener */ }
      }
      // Safari's ITP can strip window.opener across the redirect; broadcast
      // on the same channel the app listens on as a fallback.
      try {
        var channel = new BroadcastChannel('aiin_oauth');
        channel.postMessage(payload);
        channel.close();
        delivered = true;
      } catch (e) { /* unsupported */ }
      // Last resort: localStorage hand-off for older browsers.
      try {
        var existing = window.localStorage.getItem('aiin_oauth_code');
        var existingTs = existing ? (JSON.parse(existing).ts || 0) : 0;
        if (payload.ts >= existingTs) {
          window.localStorage.setItem('aiin_oauth_code', JSON.stringify(payload));
        }
        delivered = true;
      } catch (e) { /* private mode */ }

      function closePopup() {
        try { window.close(); } catch (e) { /* ignore */ }
        try {
          var named = window.open('', 'aiin_oauth');
          if (named) named.close();
        } catch (e) { /* ignore */ }
      }
      if (delivered && code) {
        closePopup();
        setTimeout(closePopup, 150);
        setTimeout(closePopup, 500);
      }

      var title = document.getElementById('title');
      var message = document.getElementById('message');
      if (code) {
        title.textContent = 'Authorized';
        title.className = 'success';
        message.textContent = delivered
          ? 'You can close this tab and return to Fa.'
          : 'The app could not be notified automatically. Copy the code '
            + 'below, close this tab, and paste it into the Fa app:'
            + '<br><br><code>' + escapeHtml(code) + '</code>';
      } else {
        title.textContent = 'Authorization failed';
        title.className = 'error';
        message.textContent = errorDescription
          ? 'Error: ' + errorDescription + '. Please close this tab and try again in the app.'
          : 'No authorization code was received. Please close this tab and try again in the app.';
      }

      function escapeHtml(text) {
        var div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
      }
    })();
  </script>
</body>
</html>

